<?php
require __DIR__.'/../config/app.php';$me=require_role('committee');ensure_committee_schema();
$events=[];$eventCount=0;$applicationCount=0;$pendingCount=0;
try{$pdo=db();$q=$pdo->prepare('SELECT COUNT(*) FROM committee_event_assignments WHERE committee_user_id=?');$q->execute([$me['id']]);$eventCount=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*),SUM(a.status=\'Pending\') FROM event_applications a JOIN committee_event_assignments cea ON cea.event_id=a.event_id WHERE cea.committee_user_id=?');$q->execute([$me['id']]);[$applicationCount,$pendingCount]=array_map('intval',$q->fetch(PDO::FETCH_NUM));$q=$pdo->prepare('SELECT e.id,e.title,e.category,e.event_date,e.venue,COUNT(a.id) applications FROM committee_event_assignments cea JOIN events e ON e.id=cea.event_id LEFT JOIN event_applications a ON a.event_id=e.id WHERE cea.committee_user_id=? GROUP BY e.id ORDER BY e.event_date LIMIT 8');$q->execute([$me['id']]);$events=$q->fetchAll();}catch(Throwable $t){}
$pageTitle='Committee Dashboard';$activePage='dashboard';$bodyClass='dashboard-page committee-page';$hideSiteNav=true;require __DIR__.'/../includes/header.php';
?><div class="dash-layout"><aside><?php require __DIR__.'/../includes/sidebar.php';?></aside><main class="content-page admin-content committee-content"><header class="admin-page-heading"><div><span class="admin-eyebrow">COMMITTEE WORKSPACE</span><h1>Welcome, <?=e($me['name'])?></h1><p>Review only the campus events assigned to your committee account.</p></div></header><div class="admin-summary-grid"><article class="admin-summary-card"><span class="admin-summary-icon teal"><?=eventhub_icon('calendar')?></span><div><small>Assigned events</small><strong><?=$eventCount?></strong></div></article><article class="admin-summary-card"><span class="admin-summary-icon violet"><?=eventhub_icon('clipboard')?></span><div><small>Applications</small><strong><?=$applicationCount?></strong></div></article><article class="admin-summary-card"><span class="admin-summary-icon orange"><?=eventhub_icon('people')?></span><div><small>Pending review</small><strong><?=$pendingCount?></strong></div></article></div><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('calendar')?></span><div><h2>Your assigned events <span class="admin-count"><?=count($events)?></span></h2><p>Use Event Applications to review applications for these events.</p></div><a href="<?=url('committee/events.php')?>">View all →</a></div><?php if($events):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Event</th><th>Category</th><th>Date</th><th>Venue</th><th>Applications</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><strong><?=e($event['title'])?></strong></td><td><span class="pill <?=e($event['category'])?>"><?=e(ucfirst($event['category']))?></span></td><td><?=date('d M Y',strtotime($event['event_date']))?></td><td><?=e($event['venue'])?></td><td><?=(int)$event['applications']?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No events are assigned to your account yet. Ask an administrator to assign an event.</div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';
